import { strToU8, zipSync } from "fflate";
import { expect, test } from "vitest";
import { parseCsv } from "./csv";
import { CELL_ERROR_PREFIX, rowToCandidate } from "./mapping";
import { MAX_XLSX_COLUMNS, MAX_XLSX_INFLATED_BYTES, parseXlsx, sniffFormat } from "./xlsx";

const b64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const parse = (bytes: Uint8Array, extra: { sheet?: string; maxRows?: number; maxInflatedBytes?: number; columns?: string[] } = {}) =>
  parseXlsx(bytes, { maxRows: 1000, ...extra });
const message = (fn: () => unknown): string => {
  try {
    fn();
  } catch (e) {
    return (e as Error).message;
  }
  return "DID NOT THROW";
};

// ---------------------------------------------------------------------------------------------
// Fixtures NOT produced by this module's reader or by fflate: FX_A is written by XlsxWriter 3.3.1
// (which reproduces Excel's own part layout, shared strings and styles), FX_C_DD is the same workbook
// re-packed by Python's zipfile onto an unseekable stream (so every entry uses a data descriptor),
// and FX_B_* are written by openpyxl 3.1.5. See the task report for the generating script.
// ---------------------------------------------------------------------------------------------
const FX_A = "";
const FX_C_DD = "";
const FX_B_TWO_SHEETS = "";
const FX_B_FORMULA = "";
const FX_B_1904 = "";

test("a workbook written by XlsxWriter parses to exactly the table Excel would show", () => {
  expect(parse(b64(FX_A))).toEqual({
    headers: ["Name", "Email", "Phone", "Phone (num)", "Zip", "Acquired", "Seen", "Total", "Active", "Note"],
    rows: [
      // text phone keeps its leading zero; a numeric phone is its exact digits; zip 1234 under "00000" is 01234;
      // dates are ISO (date-only, or UTC with the time); the formula yields its cached 3; entities are decoded.
      ["Jane & Co <J>", "jane@acme.com", "0155501234", "1555010203", "01234", "2024-03-05", "2024-03-05T13:30:15Z", "3", "TRUE", "plain bold end"],
      // 1.555010203e+19 is expanded exactly, never left in exponent form; the phone mask is applied; 1900-03-01 is
      // the first date after Excel's phantom leap day. The blank row is gone and the merged range keeps one value.
      ["Bob", "bob@acme.com", "(555) 010-0203", "15550102030000000000", "98765", "1900-03-01"],
      ["Merged"],
    ],
  });
});

test("an archive that uses data descriptors (sizes after the data) reads the same", () => {
  expect(parse(b64(FX_C_DD))).toEqual(parse(b64(FX_A)));
});

test("sheet selection: the only visible sheet by default, ambiguity and unknown names are named errors", () => {
  // FX_A has a hidden second sheet: the default is the visible one and the hidden one is not guessed.
  expect(parse(b64(FX_A)).headers[0]).toBe("Name");
  expect(parse(b64(FX_A), { sheet: "Archive" })).toEqual({ headers: ["x"], rows: [] });
  expect(message(() => parse(b64(FX_B_TWO_SHEETS)))).toBe("ambiguous_sheet: the workbook has 2 visible sheets (Leads, Other); name the one to import");
  expect(parse(b64(FX_B_TWO_SHEETS), { sheet: "Other" })).toEqual({ headers: ["Name"], rows: [["Zed"]] });
  expect(parse(b64(FX_B_TWO_SHEETS), { sheet: "Leads" })).toEqual({ headers: ["Name", "Acquired"], rows: [["Al", "2024-03-05"]] });
  expect(message(() => parse(b64(FX_B_TWO_SHEETS), { sheet: "leads" }))).toBe("sheet_not_found: \"leads\" (sheets: Leads, Other)");
});

test("the 1904 date system is honoured", () => {
  expect(parse(b64(FX_B_1904))).toEqual({ headers: ["When"], rows: [["2024-03-05"]] });
});

const UNCACHED = `${CELL_ERROR_PREFIX}uncached_formula: cell B2 has a formula but no cached value; open and re-save the workbook in Excel, or export CSV`;

test("a formula that was never calculated (openpyxl writes no cached value) rejects that cell, not the file", () => {
  expect(parse(b64(FX_B_FORMULA))).toEqual({ headers: ["A", "B"], rows: [["1", UNCACHED]] });
  // ...and is not even looked at when its column is not one the caller reads.
  expect(parse(b64(FX_B_FORMULA), { columns: ["A"] })).toEqual({ headers: ["A", "B"], rows: [["1"]] });
});

// ---------------------------------------------------------------------------------------------
// Hand-built workbooks (fflate's writer, this module's reader): shapes the real fixtures cannot reach.
// ---------------------------------------------------------------------------------------------

type Book = { sheet: string; strings?: string[]; styles?: string; epoch1904?: boolean; sheets?: Array<{ name: string; state?: string }>; extra?: Record<string, Uint8Array | string> };
const NS = 'xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"';
const REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
function book(b: Book): Uint8Array {
  const sheets = b.sheets ?? [{ name: "S" }];
  const files: Record<string, Uint8Array> = {
    "xl/workbook.xml": strToU8(
      `<workbook ${NS}>${b.epoch1904 ? '<workbookPr date1904="1"/>' : ""}<sheets>${sheets
        .map((s, i) => `<sheet name="${s.name}" sheetId="${i + 1}"${s.state ? ` state="${s.state}"` : ""} r:id="rId${i + 1}"/>`)
        .join("")}</sheets></workbook>`,
    ),
    "xl/_rels/workbook.xml.rels": strToU8(
      `<Relationships>${sheets.map((_, i) => `<Relationship Id="rId${i + 1}" Type="${REL}/worksheet" Target="worksheets/sheet${i + 1}.xml"/>`).join("")}` +
        `<Relationship Id="rIdS" Type="${REL}/styles" Target="styles.xml"/><Relationship Id="rIdT" Type="${REL}/sharedStrings" Target="sharedStrings.xml"/></Relationships>`,
    ),
    "xl/styles.xml": strToU8(b.styles ?? `<styleSheet ${NS}><cellXfs><xf numFmtId="0"/></cellXfs></styleSheet>`),
    "xl/sharedStrings.xml": strToU8(`<sst ${NS}>${(b.strings ?? []).map((s) => `<si>${s.startsWith("<") ? s : `<t>${s}</t>`}</si>`).join("")}</sst>`),
  };
  sheets.forEach((_, i) => (files[`xl/worksheets/sheet${i + 1}.xml`] = strToU8(i === 0 ? sheetXml(b.sheet) : sheetXml(""))));
  for (const [k, v] of Object.entries(b.extra ?? {})) files[k] = typeof v === "string" ? strToU8(v) : v;
  return zipSync(files, { level: 9 });
}
const sheetXml = (rows: string) => `<worksheet ${NS}><sheetData>${rows}</sheetData><rowBreaks count="0"></rowBreaks></worksheet>`;
const row = (r: number, cells: string) => `<row r="${r}">${cells}</row>`;
const s = (ref: string, idx: number) => `<c r="${ref}" t="s"><v>${idx}</v></c>`;
const n = (ref: string, v: string, style = 0) => `<c r="${ref}" s="${style}"><v>${v}</v></c>`;
const styles = (...fmts: Array<{ id: number; code?: string }>) =>
  `<styleSheet ${NS}>${fmts.some((f) => f.code) ? `<numFmts>${fmts.filter((f) => f.code).map((f) => `<numFmt numFmtId="${f.id}" formatCode="${f.code!.replace(/"/g, "&quot;")}"/>`).join("")}</numFmts>` : ""}` +
  `<cellStyleXfs><xf numFmtId="14"/></cellStyleXfs><cellXfs><xf numFmtId="0"/>${fmts.map((f) => `<xf numFmtId="${f.id}"/>`).join("")}</cellXfs></styleSheet>`;
/** One header + one numeric cell with the given number format (style 1); returns the emitted text. */
const cellOf = (value: string, fmt: { id: number; code?: string } | null, epoch1904 = false) =>
  parse(
    book({
      sheet: row(1, s("A1", 0)) + row(2, n("A2", value, fmt ? 1 : 0)),
      strings: ["H"],
      styles: styles(...(fmt ? [fmt] : [])),
      epoch1904,
    }),
  ).rows[0]![0];

test("numbers are emitted as their exact stored digits: no float round trip, no exponent form", () => {
  const cases: Array<[string, string]> = [
    ["1555010203", "1555010203"],
    ["1.555010203E9", "1555010203"],
    ["1.555010203e+19", "15550102030000000000"],
    ["123456789012345678", "123456789012345678"], // beyond double precision: only exact text survives
    ["1E-05", "0.00001"],
    ["-1.5E3", "-1500"],
    ["0.1", "0.1"],
    ["2.50E0", "2.5"],
  ];
  for (const [raw, out] of cases) expect(cellOf(raw, null)).toBe(out);
  expect(cellOf("abc", null)).toBe(`${CELL_ERROR_PREFIX}invalid_number: cell A2 holds a non-numeric value "abc"`);
  expect(cellOf("1E999", null)).toBe(`${CELL_ERROR_PREFIX}invalid_number: cell A2 has an absurd exponent`);
  expect(cellOf("9".repeat(100), null)).toBe(`${CELL_ERROR_PREFIX}invalid_number: cell A2 holds a 100 character number`);
});

test("digit-placeholder formats restore leading zeros and punctuation; other formats leave digits alone", () => {
  expect(cellOf("42", { id: 164, code: "00000" })).toBe("00042");
  expect(cellOf("123456789", { id: 164, code: "00000-0000" })).toBe("12345-6789");
  expect(cellOf("123456789", { id: 164, code: "0000" })).toBe("123456789"); // more digits than placeholders: none are lost
  expect(cellOf("5550100203", { id: 164, code: "(000) 000-0000" })).toBe("(555) 010-0203");
  expect(cellOf("1234", { id: 164, code: "#,##0" })).toBe("1234");
  expect(cellOf("3", { id: 2 })).toBe("3"); // built-in 0.00: a display detail we do not reproduce
  expect(cellOf("-7", { id: 164, code: "00000" })).toBe("-7");
  expect(cellOf("45658", null)).toBe("45658"); // General is never a date
});

test("date detection is by number format, and conversion honours Excel's epoch rules", () => {
  const date14 = { id: 14 };
  expect(cellOf("45658", date14)).toBe("2025-01-01");
  expect(cellOf("45658.5", date14)).toBe("2025-01-01T12:00:00Z");
  expect(cellOf("45658.99999999", date14)).toBe("2025-01-02"); // seconds round up into the next day
  expect(cellOf("1", date14)).toBe("1900-01-01");
  expect(cellOf("59", date14)).toBe("1900-02-28");
  expect(cellOf("61", date14)).toBe("1900-03-01");
  expect(cellOf("2958465", date14)).toBe("9999-12-31");
  expect(cellOf("0", date14, true)).toBe("1904-01-01");
  expect(cellOf("1461", date14, true)).toBe("1908-01-01"); // 1904 is a leap year: 366 + 365 * 3 days
  // custom codes
  expect(cellOf("45658", { id: 165, code: "[$-409]d-mmm-yy;@" })).toBe("2025-01-01");
  expect(cellOf("45658", { id: 165, code: "mmmm" })).toBe("2025-01-01");
  expect(cellOf("45658", { id: 165, code: '"Day "0' })).toBe("Day 45658"); // d inside quotes is a literal, not a date token
  expect(cellOf("45658", { id: 165, code: '0 "months"' })).toBe("45658 months"); // not a date: quoted text is literal
  expect(cellOf("45658", { id: 165, code: "[Red]0.00" })).toBe("45658");
  // time-only and elapsed
  expect(cellOf("0.5", { id: 166, code: "h:mm" })).toBe("12:00:00");
  expect(cellOf("1.5", { id: 167, code: "[h]:mm:ss" })).toBe("36:00:00");
});

test("a date-formatted cell that is not a real date becomes a row-rejecting marker, never a bare number", () => {
  // The mapper would read "60" as epoch milliseconds, so the value must not reach it as plain digits.
  expect(cellOf("60", { id: 14 })).toBe(
    `${CELL_ERROR_PREFIX}invalid_date: cell A2 holds 60, which is not a real calendar date (Excel serial 60 is its fictional 1900-02-29)`,
  );
  for (const bad of ["0", "-5", "2958466"]) expect(cellOf(bad, { id: 14 })).toMatch(/^#cell_error: invalid_date: cell A2 holds /);
});

test("an Excel date reaches the candidate as the right epoch milliseconds", () => {
  const { headers, rows } = parse(
    book({
      sheet: row(1, s("A1", 0) + s("B1", 1)) + row(2, s("A2", 2) + n("B2", "45658.5", 1)),
      strings: ["Site", "Acquired", "acme.com"],
      styles: styles({ id: 22 }),
    }),
  );
  const record = Object.fromEntries(headers.map((h, i) => [h, rows[0]![i]!]));
  const out = rowToCandidate(record, [{ column: "Site", target: "company.domain" }, { column: "Acquired", target: "acquisition.acquiredAt" }], 0);
  expect(out).toMatchObject({ ok: true, candidate: { acquisition: { acquiredAt: Date.UTC(2025, 0, 1, 12) } } });
});

test("formulas yield the cached value; text formulas may cache an empty string", () => {
  const cell = (xml: string) => parse(book({ sheet: row(1, s("A1", 0) + s("B1", 1)) + row(2, xml), strings: ["H", "H2"] })).rows;
  expect(cell('<c r="A2"><f>1+6</f><v>7</v></c>')).toEqual([["7"]]);
  expect(cell('<c r="A2" t="str"><f>"h"&amp;"i"</f><v>hi</v></c>')).toEqual([["hi"]]);
  expect(cell('<c r="A2" t="str"><f>""</f><v></v></c><c r="B2"><v>1</v></c>')).toEqual([["", "1"]]);
  expect(cell('<c r="A2"><f>1+6</f></c>')[0]![0]).toMatch(/^#cell_error: uncached_formula: cell A2 /);
  expect(cell('<c r="A2"><f>1+6</f><v/></c>')[0]![0]).toMatch(/^#cell_error: uncached_formula: cell A2 /);
});

test("cell types: shared and inline strings, escapes, phonetic runs, booleans, errors, ISO dates", () => {
  const out = parse(
    book({
      sheet:
        row(1, ["A", "B", "C", "D", "E", "F", "G"].map((c, i) => s(`${c}1`, 4 + i)).join("")) +
        row(
          2,
          s("A2", 1) +
            s("B2", 2) +
            '<c r="C2" t="inlineStr"><is><r><t>in</t></r><r><t xml:space="preserve"> line</t></r></is></c>' +
            '<c r="D2" t="b"><v>0</v></c>' +
            '<c r="E2" t="e"><v>#N/A</v></c>' +
            '<c r="F2" t="d"><v>2024-03-05T10:00:00Z</v></c>' +
            s("G2", 3),
        ),
      strings: ["H", "a &amp; b &#65; &#x42; &lt;x&gt; _x000D_ _x005F_x0041_", '<t>kanji</t><rPh sb="0" eb="1"><t>ignored</t></rPh>', "  padded  ", "h1", "h2", "h3", "h4", "h5", "h6", "h7"],
    }),
  );
  expect(out.rows).toEqual([["a & b A B <x> \r _x0041_", "kanji", "in line", "FALSE", `${CELL_ERROR_PREFIX}error_value: cell E2 holds the Excel error #N/A`, "2024-03-05T10:00:00Z", "  padded  "]]);
  expect(parse(book({ sheet: row(1, s("A1", 0)) + row(2, s("A2", 9)), strings: ["H"] })).rows).toEqual([
    [`${CELL_ERROR_PREFIX}invalid_shared_string: cell A2 points at missing shared string 9`],
  ]);
});

test("shape: blank rows, leading blanks, styled-empty cells, sparse columns, blank and duplicate headers", () => {
  const sst = ["Email", "", "Name", "a@x.com", "  ", "b@x.com", "Bo"];
  const out = parse(
    book({
      strings: sst,
      sheet:
        row(1, "") + // an empty row before the header
        row(2, s("A2", 0) + '<c r="B2" s="3"/>' + s("C2", 2) + '<c r="D2" s="3"/>') + // header: blank interior, styled trailing
        row(3, s("A3", 3) + s("C3", 6)) +
        row(4, s("A4", 4)) + // whitespace only: blank
        '<row r="5"/>' +
        row(6, s("C6", 5)), // sparse: A6 absent
    }),
  );
  expect(out).toEqual({ headers: ["Email", "", "Name"], rows: [["a@x.com", "", "Bo"], ["", "", "b@x.com"]] });
  const dup = book({ strings: ["A", "B"], sheet: row(1, s("A1", 0) + s("B1", 1) + s("C1", 0)) });
  expect(message(() => parse(dup))).toBe("duplicate_headers: A");
  expect(message(() => parse(book({ sheet: row(1, "") })))).toBe("empty_file: the sheet has no header row");
  expect(parse(book({ strings: ["A"], sheet: row(1, s("A1", 0)) }))).toEqual({ headers: ["A"], rows: [] });
});

test("agrees with parseCsv on the same table", () => {
  const table = [
    ["Name", "Email", "Note"],
    ["Jane", "j@x.com", "hi"],
    ["", "", ""], // a fully blank record
    ["Bob", "", "yo"],
    ["Ann", "a@x.com", ""],
  ];
  const csv = parseCsv(table.map((r) => r.join(",")).join("\n"));
  const strings = [...new Set(table.flat().filter((c) => c !== ""))];
  const rowsXml = table.map((r, i) => row(i + 1, r.map((c, j) => (c === "" ? "" : s(`${"ABC"[j]}${i + 1}`, strings.indexOf(c)))).join("")));
  const xlsx = parse(book({ strings, sheet: rowsXml.join("") }));
  // The "Ann" row ends in an empty cell; CSV keeps the trailing "" and a sheet has no cell there, so compare after
  // padding to the header width (the import reads `cells[i] ?? ""`, so the two are equivalent downstream).
  const pad = (rows: string[][]) => rows.map((r) => Array.from({ length: 3 }, (_, i) => r[i] ?? ""));
  expect(xlsx.headers).toEqual(csv.headers);
  expect(pad(xlsx.rows)).toEqual(pad(csv.rows.filter((r) => r.some((c) => c !== ""))));
});

test("a large sheet streams correctly across inflate-slice and scanner boundaries", () => {
  const N = 6000;
  const rows = [row(1, '<c r="A1" t="inlineStr"><is><t>Id</t></is></c><c r="B1" t="inlineStr"><is><t>Pad</t></is></c>')];
  for (let i = 1; i <= N; i++) rows.push(row(i + 1, n(`A${i + 1}`, String(i)) + `<c r="B${i + 1}" t="inlineStr"><is><t>${"x".repeat(i % 97)}&amp;</t></is></c>`));
  const out = parse(book({ sheet: rows.join("") }), { maxRows: N });
  expect(out.rows).toHaveLength(N);
  expect(out.rows.every((r, i) => r[0] === String(i + 1) && r[1] === "x".repeat((i + 1) % 97) + "&")).toBe(true);
});

// ------------------------------------------------------------------------------------ bounds

/** A real decompression bomb: `mib` MiB of valid rows that deflate to a small fraction of that. */
function bomb(mib: number): Uint8Array {
  const chunk = row(2, n("A2", "1")).repeat(10_000);
  const rowsXml = chunk.repeat(Math.ceil((mib * 1024 * 1024) / chunk.length));
  return book({ sheet: row(1, '<c r="A1" t="inlineStr"><is><t>H</t></is></c>') + rowsXml });
}

/** Rewrites the directory's uncompressed size of the biggest entry (the sheet) to a small lie, as a hostile archive would. */
function lieAboutSheetSize(z: Uint8Array): Uint8Array {
  const out = z.slice();
  const dv = new DataView(out.buffer);
  for (let i = 0; i + 46 < out.length; i++) {
    if (dv.getUint32(i, true) === 0x02014b50 && dv.getUint32(i + 24, true) > 1024 * 1024) dv.setUint32(i + 24, 100, true);
  }
  return out;
}

test("a real decompression bomb is refused by name while inflating, even when the directory lies about its size", () => {
  const z = lieAboutSheetSize(bomb(MAX_XLSX_INFLATED_BYTES / (1024 * 1024) + 16));
  expect(z.length).toBeLessThan(2 * 1024 * 1024); // the upload itself is small: the size gate would have passed it
  expect(message(() => parse(z, { maxRows: Number.MAX_SAFE_INTEGER }))).toBe(
    `archive_too_large: the workbook inflates past the ${MAX_XLSX_INFLATED_BYTES} byte limit (a compressed file can expand far beyond its size); split it or export CSV`,
  );
});

test("the same holds at a small budget (what comes out is counted, not what is declared)", () => {
  const z = lieAboutSheetSize(bomb(8));
  expect(message(() => parse(z, { maxInflatedBytes: 1024 * 1024, maxRows: Number.MAX_SAFE_INTEGER }))).toBe(
    "archive_too_large: the workbook inflates past the 1048576 byte limit (a compressed file can expand far beyond its size); split it or export CSV",
  );
});

test("a truthfully declared oversized part is refused before any inflation", () => {
  expect(message(() => parse(bomb(8), { maxInflatedBytes: 1024 * 1024, maxRows: Number.MAX_SAFE_INTEGER }))).toMatch(/^archive_too_large: xl\/worksheets\/sheet1\.xml declares \d+ bytes \(limit /);
});

test("the budget is shared: parts that each fit but together do not are refused", () => {
  const z = book({ sheet: row(1, s("A1", 0)), strings: ["x".repeat(3000)] });
  expect(parse(z, { maxInflatedBytes: 8000 }).headers).toHaveLength(1);
  expect(message(() => parse(z, { maxInflatedBytes: 3000 }))).toMatch(/^archive_too_large: /);
});

test("small structural parts are capped well below the total budget", () => {
  const z = book({ sheet: row(1, s("A1", 0)), strings: ["H"], styles: `<styleSheet ${NS}>${" ".repeat(5 * 1024 * 1024)}</styleSheet>` });
  expect(message(() => parse(z))).toMatch(/^archive_too_large: xl\/styles\.xml declares /);
});

test("too many rows is named and raised while parsing; exactly the limit is accepted", () => {
  const rows = (k: number) => row(1, s("A1", 0)) + Array.from({ length: k }, (_, i) => row(i + 2, n(`A${i + 2}`, String(i)))).join("");
  expect(parse(book({ sheet: rows(3), strings: ["H"] }), { maxRows: 3 }).rows).toHaveLength(3);
  expect(message(() => parse(book({ sheet: rows(4), strings: ["H"] }), { maxRows: 3 }))).toBe("too_many_rows: more than 3 rows; split the file");
});

test("data beyond the column limit is a named error; blank cells out there are not data", () => {
  const colName = (i: number): string => (i >= 26 ? colName(Math.floor(i / 26) - 1) : "") + String.fromCharCode(65 + (i % 26));
  const at = (i: number) => `<c r="${colName(i)}2"><v>1</v></c>`;
  expect(colName(MAX_XLSX_COLUMNS - 1)).toBe("AMJ");
  const ok = parse(book({ sheet: row(1, s("A1", 0)) + row(2, at(MAX_XLSX_COLUMNS - 1)), strings: ["H"] }));
  expect(ok.rows[0]).toHaveLength(MAX_XLSX_COLUMNS);
  expect(message(() => parse(book({ sheet: row(1, s("A1", 0)) + row(2, at(MAX_XLSX_COLUMNS)), strings: ["H"] })))).toBe(
    `too_many_columns: data beyond column ${MAX_XLSX_COLUMNS} (cell AMK2)`,
  );
  expect(parse(book({ sheet: row(1, s("A1", 0)) + row(2, '<c r="XFD2" s="1"/>'), strings: ["H"] })).rows).toEqual([]);
});

test("a single element larger than the buffer cap is refused rather than buffered", () => {
  const huge = row(1, `<c r="A1" t="inlineStr"><is><t>${"x".repeat(9 * 1024 * 1024)}</t></is></c>`);
  expect(message(() => parse(book({ sheet: huge })))).toBe("element_too_large: a <row> element exceeds 8388608 characters");
});

test("things that are not a readable .xlsx are named errors", () => {
  expect(message(() => parse(strToU8("a,b\n1,2\n")))).toMatch(/^not_xlsx: /);
  expect(message(() => parse(zipSync({ "word/document.xml": strToU8("<x/>") })))).toBe("not_xlsx: the archive has no xl/workbook.xml");
  const z = book({ sheet: row(1, s("A1", 0)), strings: ["H"] });
  expect(message(() => parse(z.subarray(0, z.length - 40)))).toMatch(/^not_xlsx: /); // truncated: no directory
  const bad = z.slice();
  const dv = new DataView(bad.buffer);
  for (let i = 0; i + 46 < bad.length; i++) if (dv.getUint32(i, true) === 0x04034b50) bad[i + 30 + dv.getUint16(i + 26, true) + 4] ^= 0xff; // corrupt deflate data
  expect(message(() => parse(bad))).toMatch(/^corrupt_archive: /);
  expect(message(() => parse(book({ sheet: "", sheets: [{ name: "Chart" }], extra: { "xl/_rels/workbook.xml.rels": `<Relationships><Relationship Id="rId1" Type="${REL}/chartsheet" Target="chartsheets/sheet1.xml"/></Relationships>` } })))).toMatch(
    /^not_a_worksheet: /,
  );
});

test("sniffFormat reads the bytes, not a name", () => {
  expect(sniffFormat(strToU8("PK\x03\x04rest"))).toBe("xlsx");
  expect(sniffFormat(Uint8Array.from([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]))).toBe("xls");
  expect(sniffFormat(strToU8("Name,Email\n"))).toBe("csv");
  expect(sniffFormat(new Uint8Array(0))).toBe("csv");
  expect(sniffFormat(strToU8("PK,not a zip"))).toBe("csv");
});

/** Rewrites the directory's uncompressed size of the named entry. */
function declareSize(z: Uint8Array, name: string, size: number): Uint8Array {
  const out = z.slice();
  const dv = new DataView(out.buffer);
  for (let i = 0; i + 46 < out.length; i++) {
    if (dv.getUint32(i, true) !== 0x02014b50) continue;
    const nameLen = dv.getUint16(i + 28, true);
    if (new TextDecoder().decode(out.subarray(i + 46, i + 46 + nameLen)) === name) dv.setUint32(i + 24, size, true);
  }
  return out;
}

test("a small part that lies about its size is still capped by what it really inflates to", () => {
  const z = book({ sheet: row(1, s("A1", 0)), strings: ["H"], styles: `<styleSheet ${NS}>${" ".repeat(5 * 1024 * 1024)}</styleSheet>` });
  expect(message(() => parse(declareSize(z, "xl/styles.xml", 100)))).toBe("archive_too_large: xl/styles.xml exceeds 4194304 bytes");
});

test("an entry whose inflated length disagrees with the directory is corrupt, not silently accepted", () => {
  const z = book({ sheet: row(1, s("A1", 0)), strings: ["H"] });
  const wb = new TextEncoder().encode(`<workbook ${NS}><sheets><sheet name="S" sheetId="1" r:id="rId1"/></sheets></workbook>`).length;
  expect(message(() => parse(declareSize(z, "xl/workbook.xml", wb - 1)))).toBe(`corrupt_archive: xl/workbook.xml inflated to ${wb} bytes, directory says ${wb - 1}`);
});

// ------------------------------------------------------------------ a bad cell is data, not an exception

/** Header Name | Email | Notes | When; row 2 has a good name and email, a typo'd date (serial 60) in When and an error value in Notes. */
const badCells = () =>
  book({
    strings: ["Name", "Email", "Notes", "When", "Ann", "ann@x.com"],
    styles: styles({ id: 14 }),
    sheet:
      row(1, s("A1", 0) + s("B1", 1) + s("C1", 2) + s("D1", 3)) +
      row(2, s("A2", 4) + s("B2", 5) + '<c r="C2" t="e"><v>#N/A</v></c>' + n("D2", "60", 1)) +
      row(3, s("A3", 4) + s("B3", 5) + '<c r="C3" t="str"><f>x</f><v>ok</v></c>' + n("D3", "45658", 1)),
  });
const D_ERR = `${CELL_ERROR_PREFIX}invalid_date: cell D2 holds 60, which is not a real calendar date (Excel serial 60 is its fictional 1900-02-29)`;

test("only mapped columns are interpreted: bad cells elsewhere cannot touch the import", () => {
  expect(parse(badCells(), { columns: ["Name", "Email"] })).toEqual({
    headers: ["Name", "Email", "Notes", "When"],
    rows: [["Ann", "ann@x.com"], ["Ann", "ann@x.com"]],
  });
  // Mapped, the same cells become markers (exact text), and the good row beside them is untouched.
  expect(parse(badCells(), { columns: ["Name", "When"] }).rows).toEqual([["Ann", "", "", D_ERR], ["Ann", "", "", "2025-01-01"]]);
});

test("unmapped columns still count as data, so row numbers and blank-row handling match the CSV reading", () => {
  const z = book({
    strings: ["Name", "Notes", "Ann", "only a note"],
    sheet: row(1, s("A1", 0) + s("B1", 1)) + row(2, s("A2", 2)) + row(3, s("B3", 3)) + row(4, ""),
  });
  expect(parse(z, { columns: ["Name"] }).rows).toEqual([["Ann"], []]); // row 3 has data only in an unmapped column: kept, as in CSV
  expect(parse(z).rows).toEqual([["Ann"], ["", "only a note"]]);
});

test("data beyond the column cap in an unmapped column is still the file's problem", () => {
  const z = book({ strings: ["Name"], sheet: row(1, s("A1", 0)) + row(2, '<c r="AMK2"><v>1</v></c>') });
  expect(message(() => parse(z, { columns: ["Name"] }))).toBe(`too_many_columns: data beyond column ${MAX_XLSX_COLUMNS} (cell AMK2)`);
});

test("a marker rejects its row with a reason naming the cell, for any target, and never imports a value", () => {
  const { headers, rows } = parse(badCells(), { columns: ["Name", "Email", "Notes", "When"] });
  const rec = (r: string[]) => Object.fromEntries(headers.map((h, i) => [h, r[i] ?? ""]));
  const pairs = [
    { column: "Name", target: "person.fullName" },
    { column: "Email", target: "person.email" },
    { column: "Notes", target: "person.jobTitle" }, // a text target: "#N/A" as plain text would have been accepted
    { column: "When", target: "acquisition.acquiredAt" },
  ];
  const bad = rowToCandidate(rec(rows[0]!), pairs, 0);
  expect(bad).toEqual({
    ok: false,
    errors: [
      `person.jobTitle: error_value: cell C2 holds the Excel error #N/A (column "Notes")`,
      `acquisition.acquiredAt: invalid_date: cell D2 holds 60, which is not a real calendar date (Excel serial 60 is its fictional 1900-02-29) (column "When")`,
    ],
  });
  expect(rowToCandidate(rec(rows[1]!), pairs, 0)).toMatchObject({ ok: true, candidate: { acquisition: { acquiredAt: Date.UTC(2025, 0, 1) } } });
});

// ------------------------------------------------------------------ work is bounded, not just bytes

/** Wall-clock budget for hostile-input tests. Linear scans finish in well under a second; the quadratic scan this guards
 *  against took 61.7 s on the same 200,000-token payload, so the margin is five orders of magnitude and this is not flaky. */
const WORK_BUDGET_MS = 5_000;
const timed = <T>(fn: () => T): { out: T; ms: number } => {
  const t0 = performance.now();
  const out = fn();
  return { out, ms: performance.now() - t0 };
};

test("200,000 unterminated <c tokens in a ~1 KB upload fail by name, fast (the quadratic cell scan)", () => {
  const z = book({ sheet: row(1, s("A1", 0)) + `<row r="2">${"<c ".repeat(200_000)}</row>`, strings: ["H"] });
  expect(z.length).toBeLessThan(4_000);
  const { out, ms } = timed(() => message(() => parse(z)));
  expect(out).toBe("corrupt_workbook: an unterminated or oversized <c> tag");
  expect(ms).toBeLessThan(WORK_BUDGET_MS);
  // the variant where a '>' does eventually arrive, so the tag is "terminated" but absurd
  const far = book({ sheet: row(1, s("A1", 0)) + `<row r="2">${"<c ".repeat(200_000)}></row>`, strings: ["H"] });
  const farOut = timed(() => message(() => parse(far)));
  expect(farOut.out).toBe("corrupt_workbook: an unterminated or oversized <c> tag");
  expect(farOut.ms).toBeLessThan(WORK_BUDGET_MS);
  // and the cap on the number of cells itself
  const many = book({ sheet: row(1, s("A1", 0)) + `<row r="2">${"<c/>".repeat(200_000)}</row>`, strings: ["H"] });
  const manyOut = timed(() => message(() => parse(many)));
  expect(manyOut.out).toBe("too_many_columns: a row has more than 16384 cells");
  expect(manyOut.ms).toBeLessThan(WORK_BUDGET_MS);
});

test("200,000 well-formed-looking but unclosed <c a=\"1\"> tokens are refused by name, fast", () => {
  const z = book({ sheet: row(1, s("A1", 0)) + `<row r="2">${'<c r="A2">'.repeat(20_000)}</row>`, strings: ["H"] });
  const { out, ms } = timed(() => message(() => parse(z)));
  expect(out).toBe("corrupt_workbook: a <c> element is never closed");
  expect(ms).toBeLessThan(WORK_BUDGET_MS);
});

test("an unterminated <c tag is refused by name, fast", () => {
  const z = book({ sheet: row(1, s("A1", 0)) + `<row r="2"><c r="A2" ${"x ".repeat(100_000)}</row>`, strings: ["H"] });
  const { out, ms } = timed(() => message(() => parse(z)));
  expect(out).toMatch(/^corrupt_workbook: an unterminated or oversized <c> tag$/);
  expect(ms).toBeLessThan(WORK_BUDGET_MS);
});

test("unterminated <t and <rPh tokens in a shared string do not make the string scan quadratic", () => {
  for (const evil of ["<t>".repeat(80_000), "<rPh>".repeat(80_000), "<t>x</t><rPh>".repeat(1) + "<t>".repeat(80_000)]) {
    const z = book({ sheet: row(1, s("A1", 0)), strings: [evil] });
    const { out, ms } = timed(() => message(() => parse(z)));
    expect(out).toBe("corrupt_workbook: xl/sharedStrings.xml has a malformed string item");
    expect(ms).toBeLessThan(WORK_BUDGET_MS);
  }
  // ...and the same inside an inline string is a bad cell, not a bad file
  const inline = book({ sheet: row(1, s("A1", 0)) + row(2, `<c r="A2" t="inlineStr"><is>${"<t>".repeat(80_000)}</is></c>`), strings: ["H"] });
  const { out, ms } = timed(() => parse(inline).rows);
  expect(out).toEqual([[`${CELL_ERROR_PREFIX}malformed_cell: <t> is never closed`]]);
  expect(ms).toBeLessThan(WORK_BUDGET_MS);
});

test("hostile numbers and number formats are bounded too", () => {
  const { out, ms } = timed(() => cellOf("1".repeat(2_000_000) + "x", null));
  expect(out).toMatch(/^#cell_error: invalid_number: cell A2 holds a 2000001 character number$/);
  expect(ms).toBeLessThan(WORK_BUDGET_MS);
  expect(cellOf("45658", { id: 170, code: "[".repeat(300) })).toBe("45658"); // an implausibly long format is not interpreted
  expect(message(() => cellOf("45658", { id: 170, code: "[".repeat(200_000) }))).toBe("corrupt_workbook: an unterminated or oversized <numFmt> tag");
});

test("unterminated structural tags in the workbook parts are refused by name, fast", () => {
  const z = book({ sheet: row(1, s("A1", 0)), strings: ["H"], styles: `<styleSheet ${NS}><cellXfs>${"<xf ".repeat(300_000)}</cellXfs></styleSheet>` });
  const { out, ms } = timed(() => message(() => parse(z)));
  expect(out).toMatch(/^corrupt_workbook: /);
  expect(ms).toBeLessThan(WORK_BUDGET_MS);
});

test("a legal '>' inside an attribute value does not mis-split a cell", () => {
  const z = book({ strings: ["H"], sheet: row(1, s("A1", 0)) + row(2, '<c r="A2" t="inlineStr" x="a>b"><is><t>kept</t></is></c>') });
  expect(parse(z).rows).toEqual([["kept"]]);
});

test("a malformed cell reference is a corrupt workbook, not a misleading too_many_columns", () => {
  for (const r of ["12", "?7", "1A"]) {
    const z = book({ strings: ["H"], sheet: row(1, s("A1", 0)) + row(2, `<c r="${r}" t="inlineStr"><is><t>x</t></is></c>`) });
    expect(message(() => parse(z))).toBe(`corrupt_workbook: malformed cell reference "${r}"`);
  }
});

// ------------------------------------------------------------------ mapped vs unmapped consistency

test("whitespace-only cells in unmapped columns are blank exactly as they are when interpreted", () => {
  const z = book({
    strings: ["Name", "Notes", "Ann", "   ", "real"],
    sheet:
      row(1, s("A1", 0) + s("B1", 1)) +
      row(2, s("A2", 2)) +
      row(3, '<c r="B3" t="inlineStr"><is><t xml:space="preserve">  </t></is></c>') + // inline whitespace
      row(4, s("B4", 3)) + // shared-string whitespace
      row(5, '<c r="B5"><v> </v></c>') + // numeric-typed whitespace
      row(6, s("B6", 4)),
  });
  const withColumns = parse(z, { columns: ["Name"] });
  const without = parse(z);
  expect(withColumns.rows).toEqual([["Ann"], []]); // rows 3-5 are blank; row 6 has real data in an unmapped column
  expect(without.rows).toEqual([["Ann"], ["", "real"]]);
  expect(withColumns.rows).toHaveLength(without.rows.length);
});

test("an unmapped cell that is garbage imports cleanly with columns, and cannot fail the file either way", () => {
  const z = book({
    strings: ["Name", "Notes", "Ann"],
    sheet:
      row(1, s("A1", 0) + s("B1", 1)) +
      row(2, s("A2", 2) + '<c r="B2"><v>not-a-number</v></c>') + // garbage number
      row(3, s("A3", 2) + '<c r="B3" t="s"><v>99</v></c>') + // dangling shared string
      row(4, s("A4", 2) + '<c r="B4" t="inlineStr"><is><t>never closed</is></c>'), // malformed
  });
  expect(parse(z, { columns: ["Name"] }).rows).toEqual([["Ann"], ["Ann"], ["Ann"]]);
  // Interpreted, each is a marker in that cell only; the good cell beside it is untouched.
  const all = parse(z).rows;
  expect(all.map((r) => r[0])).toEqual(["Ann", "Ann", "Ann"]);
  expect(all[0]![1]).toBe(`${CELL_ERROR_PREFIX}invalid_number: cell B2 holds a non-numeric value "not-a-number"`);
  expect(all[1]![1]).toBe(`${CELL_ERROR_PREFIX}invalid_shared_string: cell B3 points at missing shared string 99`);
  expect(all[2]![1]).toMatch(/^#cell_error: malformed_cell: /);
});
